UPDATE public.tutorial_videos SET walkthrough_frames='[{"step": 1, "label": "Open Attendance from the teacher menu", "route": "/attendance", "path": "attendance-marking/step-01.png", "hotspot": {"x": 0.2778, "y": 0.2344}}, {"step": 2, "label": "The tiles summarise scheduled, present, absent, rescheduled and missing classes", "route": null, "path": "attendance-marking/step-02.png", "hotspot": {"x": 0.6016, "y": 0.2344}}, {"step": 3, "label": "Every marked class lists the exact Nazra lesson covered that day", "route": null, "path": "attendance-marking/step-03.png", "hotspot": {"x": 0.6641, "y": 0.5067}}, {"step": 4, "label": "Filter by month, date range or this week to find a class", "route": null, "path": "attendance-marking/step-04.png", "hotspot": {"x": 0.7184, "y": 0.3433}}, {"step": 5, "label": "Press Mark Attendance to open the form", "route": null, "path": "attendance-marking/step-05.png", "hotspot": {"x": 0.9301, "y": 0.0978}}, {"step": 6, "label": "Pick the student — the subject shows next to the name", "route": null, "path": "attendance-marking/step-06.png", "hotspot": {"x": 0.3184, "y": 0.2989}}, {"step": 7, "label": "Choose the Nazra student from the list", "route": null, "path": "attendance-marking/step-07.png", "hotspot": {"x": 0.3629, "y": 0.3489}}, {"step": 8, "label": "Tap the status pill — Present, Absent, Leave or Rescheduled", "route": null, "path": "attendance-marking/step-08.png", "hotspot": {"x": 0.4531, "y": 0.3411}}, {"step": 9, "label": "Class Date only lists the student''s scheduled class days", "route": null, "path": "attendance-marking/step-09.png", "hotspot": {"x": 0.2898, "y": 0.4428}}, {"step": 10, "label": "The scheduled time fills in automatically from the weekly slot", "route": null, "path": "attendance-marking/step-10.png", "hotspot": {"x": 0.6246, "y": 0.5361}}, {"step": 11, "label": "Lesson Today shows the last lesson — pick New Lesson or Same as last class", "route": null, "path": "attendance-marking/step-11.png", "hotspot": {"x": 0.3125, "y": 0.7}}, {"step": 12, "label": "In Today''s Lesson choose how to enter it: Type it or Tap on page", "route": null, "path": "attendance-marking/step-12.png", "hotspot": {"x": 0.3234, "y": 0.8333}}, {"step": 13, "label": "Choose the marker unit: Ruku, Ayah, Quarter (Juz for Hifz)", "route": null, "path": "attendance-marking/step-13.png", "hotspot": {"x": 0.3479, "y": 0.9311}}, {"step": 14, "label": "Set the From and To Surah and Ayah — the total is counted for you", "route": null, "path": "attendance-marking/step-14.png", "hotspot": {"x": 0.6641, "y": 0.5739}}, {"step": 15, "label": "Tap on page opens the real Mushaf — tap the start and end word", "route": null, "path": "attendance-marking/step-15.png", "hotspot": {"x": 0.6219, "y": 0.8778}}, {"step": 16, "label": "Add another segment when the lesson covers separate portions", "route": null, "path": "attendance-marking/step-16.png", "hotspot": {"x": 0.3484, "y": 0.95}}, {"step": 17, "label": "Voice note & remarks stay collapsed — open them when needed", "route": null, "path": "attendance-marking/step-17.png", "hotspot": {"x": 0.5, "y": 0.96}}, {"step": 18, "label": "Press Mark Attendance in the bottom bar to save", "route": null, "path": "attendance-marking/step-18.png", "hotspot": {"x": 0.6957, "y": 0.9233}}]'::jsonb, walkthrough_error=NULL, walkthrough_status='ready', updated_at=now() WHERE tutorial_key='attendance-marking' AND language='en';
UPDATE public.tutorial_videos SET walkthrough_frames='[{"step": 1, "label": "استاد کے مینو سے Attendance کھولیں", "route": "/attendance", "path": "attendance-marking/step-01.png", "hotspot": {"x": 0.2778, "y": 0.2344}}, {"step": 2, "label": "اوپر کے خانے شیڈول، حاضر، غیر حاضر، ری شیڈول اور باقی ماندہ کا خلاصہ ہیں", "route": null, "path": "attendance-marking/step-02.png", "hotspot": {"x": 0.6016, "y": 0.2344}}, {"step": 3, "label": "ہر درج شدہ کلاس کے سامنے اُس دن کا ناظرہ سبق لکھا ہوتا ہے", "route": null, "path": "attendance-marking/step-03.png", "hotspot": {"x": 0.6641, "y": 0.5067}}, {"step": 4, "label": "مہینہ، تاریخ کی حد یا اس ہفتے کے فلٹر سے کلاس تلاش کریں", "route": null, "path": "attendance-marking/step-04.png", "hotspot": {"x": 0.7184, "y": 0.3433}}, {"step": 5, "label": "Mark Attendance دبائیں تاکہ فارم کھلے", "route": null, "path": "attendance-marking/step-05.png", "hotspot": {"x": 0.9301, "y": 0.0978}}, {"step": 6, "label": "طالبعلم منتخب کریں — نام کے ساتھ مضمون بھی نظر آتا ہے", "route": null, "path": "attendance-marking/step-06.png", "hotspot": {"x": 0.3184, "y": 0.2989}}, {"step": 7, "label": "فہرست میں سے ناظرہ کا طالبعلم منتخب کریں", "route": null, "path": "attendance-marking/step-07.png", "hotspot": {"x": 0.3629, "y": 0.3489}}, {"step": 8, "label": "حالت کا بٹن دبائیں — حاضر، غیر حاضر، رخصت یا ری شیڈول", "route": null, "path": "attendance-marking/step-08.png", "hotspot": {"x": 0.4531, "y": 0.3411}}, {"step": 9, "label": "کلاس کی تاریخ میں صرف شیڈول شدہ دن نظر آتے ہیں", "route": null, "path": "attendance-marking/step-09.png", "hotspot": {"x": 0.2898, "y": 0.4428}}, {"step": 10, "label": "کلاس کا وقت ہفتہ وار شیڈول سے خود بھر جاتا ہے", "route": null, "path": "attendance-marking/step-10.png", "hotspot": {"x": 0.6246, "y": 0.5361}}, {"step": 11, "label": "Lesson Today پچھلا سبق دکھاتا ہے — نیا سبق یا وہی سبق منتخب کریں", "route": null, "path": "attendance-marking/step-11.png", "hotspot": {"x": 0.3125, "y": 0.7}}, {"step": 12, "label": "Today''s Lesson میں طریقہ منتخب کریں: خود لکھیں یا صفحے پر ٹیپ کریں", "route": null, "path": "attendance-marking/step-12.png", "hotspot": {"x": 0.3234, "y": 0.8333}}, {"step": 13, "label": "مارکر منتخب کریں: رکوع، آیت، پارے کا حصہ (حفظ کے لیے پارہ)", "route": null, "path": "attendance-marking/step-13.png", "hotspot": {"x": 0.3479, "y": 0.9311}}, {"step": 14, "label": "شروع اور آخر کی سورت اور آیت درج کریں — کل تعداد خود شمار ہو جاتی ہے", "route": null, "path": "attendance-marking/step-14.png", "hotspot": {"x": 0.6641, "y": 0.5739}}, {"step": 15, "label": "Tap on page اصل مصحف کھولتا ہے — شروع اور آخر کا لفظ ٹیپ کریں", "route": null, "path": "attendance-marking/step-15.png", "hotspot": {"x": 0.6219, "y": 0.8778}}, {"step": 16, "label": "اگر سبق الگ الگ حصوں پر مشتمل ہو تو مزید حصہ شامل کریں", "route": null, "path": "attendance-marking/step-16.png", "hotspot": {"x": 0.3484, "y": 0.95}}, {"step": 17, "label": "وائس نوٹ اور تبصرہ بند رہتے ہیں — ضرورت پر کھولیں", "route": null, "path": "attendance-marking/step-17.png", "hotspot": {"x": 0.5, "y": 0.96}}, {"step": 18, "label": "نیچے موجود Mark Attendance دبا کر محفوظ کریں", "route": null, "path": "attendance-marking/step-18.png", "hotspot": {"x": 0.6957, "y": 0.9233}}]'::jsonb, walkthrough_error=NULL, walkthrough_status='ready', updated_at=now() WHERE tutorial_key='attendance-marking' AND language='ur';